{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection via Dynamic Query",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "4-7",
      "explanation": "The method concatenates the caller-provided searchKey directly into a dynamic SOQL string without escaping or binding, allowing an attacker to inject arbitrary SOQL clauses and potentially read or modify data beyond their permissions.",
      "remediation": "Replace the dynamic query with a static SOQL statement that uses a bind variable, e.g. `SELECT Id, Name, Industry FROM Account WHERE Name LIKE :('%' + String.escapeSingleQuotes(searchKey) + '%') LIMIT 50`, or use `Database.queryWithBinds` with an allow‑list for field names."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Field-Level Security Violation",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "3-6",
      "explanation": "The method queries and returns the Email and Birthdate fields, which are not readable by users with the Contact Phone Editor permission set. Apex runs in system mode and ignores FLS unless explicitly enforced, so users can view data they should not see.",
      "remediation": "Enforce FLS by using WITH SECURITY_ENFORCED in the SOQL query, or by calling Security.stripInaccessible on the queried fields, or by removing the non‑required fields from the query."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Record-level sharing bypass in @AuraEnabled method",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "1-12",
      "explanation": "The class is declared \"without sharing\", so record-level sharing rules are ignored. Because the method is exposed via @AuraEnabled, any user with the permission set can invoke it and retrieve cases they should not see, bypassing sharing restrictions.",
      "remediation": "Declare the class with \"with sharing\" or \"inherited sharing\", or add a WITH SHARE clause to the SOQL query. This ensures that only records the user is allowed to see are returned."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive permissions in Support Agent Tools permission set",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "all",
      "explanation": "The permission set grants ModifyAllData and ViewAllData, which allow users to bypass all sharing and field-level security on every object. This far exceeds the described purpose of only viewing and closing cases.",
      "remediation": "Remove the ModifyAllData and ViewAllData permissions from the permission set. Grant only the necessary Case object permissions (Read, Edit) and any other minimal permissions required for the support agent role."
    }
  ]
}
